import{_ as a,o,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"篇156｜境界细化·创世境·掠夺派vs共生派对比","description":"","frontmatter":{"title":"篇156｜境界细化·创世境·掠夺派vs共生派对比","no":156,"module":1,"tags":["境界","创世境","掠夺派","共生派","路线对比"],"related":["0014-修炼境界统一划分","0004-反掠夺主义核心论纲","0005-万族共进基本纲领"]},"headers":[],"relativePath":"zh/0156_模块1-创世境-掠夺派vs共生派对比.md","filePath":"zh/0156_模块1-创世境-掠夺派vs共生派对比.md"}'),d={name:"zh/0156_模块1-创世境-掠夺派vs共生派对比.md"};function l(s,t,u,h,i,n){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="篇156-创世境-掠夺派vs共生派详细对比" tabindex="-1">篇156｜创世境：掠夺派vs共生派详细对比 <a class="header-anchor" href="#篇156-创世境-掠夺派vs共生派详细对比" aria-label="Permalink to &quot;篇156｜创世境：掠夺派vs共生派详细对比&quot;">​</a></h1><blockquote><p>所属模块：模块一·境界深度细化｜对标地基：文档14、04、05</p></blockquote><h2 id="引言-神国与良田-一字之差" tabindex="-1">引言：神国与良田，一字之差 <a class="header-anchor" href="#引言-神国与良田-一字之差" aria-label="Permalink to &quot;引言：神国与良田，一字之差&quot;">​</a></h2><p>创世境把两种文明路线的分歧推到了&quot;造世界&quot;这个最富诱惑的舞台。按《修炼境界统一划分》（文档14），创世=造一个含生命的完整世界。这件事落到<strong>掠夺派</strong>手里，是给自己造一座神国；落到<strong>共生派</strong>手里，是给万族造一块良田。本文把两种路线在创世境的完整差异摆上台面。</p><p>贯穿全文的六大顶层公理，仍是共生派对掠夺派的逐条反命题：万族共和公理反对&quot;神国里众生是奴隶&quot;；集体升维公理反对&quot;造物主独自成神&quot;；反掠夺主义公理反对&quot;以创世吞并存量&quot;；因果自律与法则优先则反对&quot;剧情式独裁&quot;。依据《反掠夺主义核心论纲》（文档04）与《万族共进基本纲领》（文档05），展开系统对比。其中第六条众生全员无限均等法则确立了人人自带基础无限之力、掠夺失去意义的本源逻辑。</p><h2 id="一、总览对比表" tabindex="-1">一、总览对比表 <a class="header-anchor" href="#一、总览对比表" aria-label="Permalink to &quot;一、总览对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>掠夺派创世者</th><th>共生派创世者</th></tr></thead><tbody><tr><td>世界性质</td><td>神国/后花园，归创造者私有</td><td>公共世界田，归万族共建</td></tr><tr><td>世界内众生</td><td>奴隶、韭菜、NPC、唯一主角的陪衬</td><td>拥有平等进化资格的生命</td></tr><tr><td>法则设计</td><td>围绕创造者特权设计</td><td>围绕众生福祉与自洽设计</td></tr><tr><td>开放程度</td><td>私锁，外人不得入</td><td>向万族开放，登记联产承包</td></tr><tr><td>与既有宇宙</td><td>常吞并改造既有位面</td><td>纯增量新建，不扰动因果</td></tr><tr><td>终局</td><td>创造者死亡即神国崩塌</td><td>世界永续运行，造福后世</td></tr><tr><td>心性要求</td><td>无，独裁者通吃</td><td>反掠夺立场+众生资格审查</td></tr></tbody></table><h2 id="二、世界性质-神国-vs-良田" tabindex="-1">二、世界性质：神国 vs 良田 <a class="header-anchor" href="#二、世界性质-神国-vs-良田" aria-label="Permalink to &quot;二、世界性质：神国 vs 良田&quot;">​</a></h2><p>掠夺派创世的第一动机是&quot;这个世界归我统治&quot;。他设计世界的一切——法则、资源、众生——都围绕&quot;让我成为这里的唯一主宰&quot;。世界是他的神国，他是唯一的真神。</p><p>共生派创世的第一动机是&quot;万族需要一块新的修炼田&quot;。他设计世界的一切都围绕&quot;让这里的众生能平等、自由、可持续地进化&quot;。世界是公共良田，他是耕耘者，不是地主。</p><p>一个判断标准即可分辨：这个世界离开造物主后，会继续健康运行，还是会立刻崩溃？前者是良田，后者是神国——神国离了神就塌，良田离了农人照样长庄稼。</p><h2 id="三、众生地位-奴隶-vs-主人" tabindex="-1">三、众生地位：奴隶 vs 主人 <a class="header-anchor" href="#三、众生地位-奴隶-vs-主人" aria-label="Permalink to &quot;三、众生地位：奴隶 vs 主人&quot;">​</a></h2><p>掠夺派世界里，众生是工具。典型剧本：设计一个&quot;唯一天选主角&quot;，其余众生是陪衬、韭菜、炮灰；或者把众生设计成永远俯首帖耳的仆从，剥夺其进化上限。这是把&quot;万族共和&quot;踩在脚下。</p><p>共生派世界里，众生是自己的主人。世界底层法则就写着平等进化资格，预留自治空间，让众生自己发展文明、自己选择道路。造物主只做兜底，不做遥控。</p><h2 id="四、资源与因果-吞并-vs-增量" tabindex="-1">四、资源与因果：吞并 vs 增量 <a class="header-anchor" href="#四、资源与因果-吞并-vs-增量" aria-label="Permalink to &quot;四、资源与因果：吞并 vs 增量&quot;">​</a></h2><p>掠夺派创世常&quot;挂羊头卖狗肉&quot;：名义上造新世界，实则把既有位面改造成私产，或抽取本宇宙本源灌注自己的神国——本质是零和掠夺。</p><p>共生派创世是纯增量：在隔离空间里用增量资源造新世界，不碰本位面存量，不扰动既有因果。世界的存在让宇宙的可耕种面积变大，而非被瓜分。</p><h2 id="五、开放与终局-私锁-vs-永续" tabindex="-1">五、开放与终局：私锁 vs 永续 <a class="header-anchor" href="#五、开放与终局-私锁-vs-永续" aria-label="Permalink to &quot;五、开放与终局：私锁 vs 永续&quot;">​</a></h2><p>掠夺派的世界私锁，外人不得入，知识与技术垄断其中。其终局脆弱：创造者一旦陨落，神国失去维系，众生重回苦海。</p><p>共生派的世界开放，蓝图与经验全网共享。其终局永续：世界建成后自主运行，造物主晋升离去，良田继续造福万代。这正是主角唯一性依赖度从&quot;极高&quot;降到&quot;极低&quot;的关键——世界不依赖某一个神。</p><h2 id="六、典型结局对比" tabindex="-1">六、典型结局对比 <a class="header-anchor" href="#六、典型结局对比" aria-label="Permalink to &quot;六、典型结局对比&quot;">​</a></h2><ul><li>掠夺派创世者：神国里众生匍匐，他享受一时的至高，最终在内斗、反叛或自身陨落中神国崩塌</li><li>共生派创世者：公共世界田繁荣，他本人逐级晋升本源、多元，成为万族网络的永久节点</li></ul><h2 id="七、五大核心落点" tabindex="-1">七、五大核心落点 <a class="header-anchor" href="#七、五大核心落点" aria-label="Permalink to &quot;七、五大核心落点&quot;">​</a></h2><ul><li><strong>全员无限兜底</strong>：众生全员无限均等法则确立人人自带基础无限之力，佛系懒狗有保底、卷王少年至尊可叠加，掠夺自然失去意义</li><li><strong>反能级浪费</strong>：掠夺派把宇宙最稀缺的&quot;世界设计能力&quot;浪费在造私产神国；共生派把它转成万族永久良田</li><li><strong>反掠夺</strong>：本条即主旨——神国与良田，一私一公，文明两途</li><li><strong>唐罗上限对比</strong>：唐罗式创世者造一个以自己为绝对主角的宇宙；衡元宙创世者造一个众生平等的公共世界</li><li><strong>万族全覆盖</strong>：共生派世界默认五谱系众生有路；掠夺派世界只有一个神和一群奴才</li><li><strong>超多元全开放</strong>：共生派的世界蓝图、生态、法则全开放；掠夺派的神国永不开放</li></ul><p>还要补一句常被忽略的差异：掠夺派的神国往往&quot;越造越封闭&quot;，因为它要防止外人进来分走权力；共生派的良田却&quot;越造越开放&quot;，因为它欢迎万族来耕种、来生活。封闭与开放，看似只是城门的开合，实则是两种文明对&quot;世界属于谁&quot;的根本回答——神国属于神，良田属于所有肯播种的人。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>创世境是&quot;造物主之心&quot;的试金石。同一个造世界的能力，用来成神还是用来耕田，决定了一个人是掠夺派还是共生派。神国再辉煌，也只是一个人的舞台；良田再朴素，也是万代众生的家园。衡元宙的选择，从来不是&quot;能不能造世界&quot;，而是&quot;造一个谁的世界&quot;。</p><p>说到底，本篇所述的创世境·掠夺派vs共生派对比并非孤例——始终指向锚点共生文明的共建方向；其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校；法则自洽性由法则优先公理兜底，不随叙事便利而漂移。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0014-修炼境界统一划分.html">0014-修炼境界统一划分</a> · <a href="./0004-反掠夺主义核心论纲.html">0004-反掠夺主义核心论纲</a> · <a href="./0005-万族共进基本纲领.html">0005-万族共进基本纲领</a> · <a href="./0017-位面至高强者标准.html">0017-位面至高强者标准</a></li></ul>',30)])])}const _=a(d,[["render",l]]);export{p as __pageData,_ as default};
